/**
 * Keeps the original single-transaction quoted-data workload as an enabled autogrow regression. The paired tests differ
 * only by whether a read-committed triple-term cursor is held while the identical writer transaction commits.
 */
@ResourceLock("lmdb-resize-loggers")
class LmdbAutogrowSingleCommitIT {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:lmdb-autogrow:isolation:predicate");
	private static final int ROWS = 32_768;
	private static final int VALUE_LENGTH = 160;
	private static final int SEPARATE_BATCH_ROWS = 1_024;
	private static final int SEPARATE_BATCH_LARGE_VALUE_LENGTH = 262_144;
	private static final int PINNED_PREPARED_BATCH_ROWS = 32_768;

	@TempDir
	Path dataDir;

	@Test
	@Timeout(60)
	void singleQuotedCommitCompletesWithHeldReadCommittedReader() throws Exception {
		exerciseSingleQuotedCommit(true);
	}

	@Test
	@Timeout(60)
	void singleQuotedCommitCompletesWithoutHeldReader() throws Exception {
		exerciseSingleQuotedCommit(false);
	}

	@Test
	@Timeout(60)
	void separatelyApprovedPreparedBatchesReserveAgainstTheActiveWriter() throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), autoGrowConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			try (ResizeLogCapture resizeLogs = ResizeLogCapture.open();
					SailSink sink = store.getBackingStore()
							.getExplicitSailSource()
							.sink(IsolationLevels.READ_COMMITTED)) {
				Model firstBatch = preparedRows(0, SEPARATE_BATCH_ROWS, 1);
				Model secondBatch = preparedRows(SEPARATE_BATCH_ROWS, SEPARATE_BATCH_ROWS,
						SEPARATE_BATCH_LARGE_VALUE_LENGTH);
				sink.approveAll(firstBatch);
				sink.approveAll(secondBatch);
				sink.flush();

				assertThat(resizeLogs.valueResizeMessages())
						.as("each separately approved prepared batch must reserve its own value footprint; resizes=%s",
								resizeLogs.valueResizeMessages())
						.hasSizeGreaterThan(1);
				assertThat(countRows(repository)).isEqualTo(2 * SEPARATE_BATCH_ROWS);
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void preparedBatchesPreserveExactQuotedStatementsAcrossPinnedReaderResize() throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), autoGrowConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();

		Model firstBatch = preparedQuotedRows(0, SEPARATE_BATCH_ROWS);
		Model secondBatch = preparedRows(SEPARATE_BATCH_ROWS, PINNED_PREPARED_BATCH_ROWS, VALUE_LENGTH);
		Model expected = new LinkedHashModel();
		expected.addAll(firstBatch);
		expected.addAll(secondBatch);
		Set<TripleTerm> expectedTripleTerms = new HashSet<>();
		firstBatch.forEach(statement -> expectedTripleTerms.add((TripleTerm) statement.getObject()));
		ValueStore valueStore = (ValueStore) store.getBackingStore().getValueFactory();
		try {
			try (ResizeLogCapture resizeLogs = ResizeLogCapture.open();
					SailSink sink = store.getBackingStore()
							.getExplicitSailSource()
							.sink(IsolationLevels.READ_COMMITTED)) {
				sink.approveAll(firstBatch);
				sink.flush();
				int resizesBeforePinnedReader = resizeLogs.valueResizeMessages().size();
				long predicateId = valueStore.getId(PREDICATE);
				try (RecordIterator heldTriples = valueStore.getTripleTerms(-1, predicateId, -1)) {
					long[] firstQuad = heldTriples.next();
					assertThat(firstQuad).as("the committed first prepared batch must be readable").isNotNull();
					sink.approveAll(secondBatch);
					sink.flush();
					assertThat(resizeLogs.valueResizeMessages().size())
							.as("the second prepared batch must resize while a native value reader is held")
							.isGreaterThan(resizesBeforePinnedReader);

					Set<TripleTerm> actualTripleTerms = new HashSet<>();
					actualTripleTerms.add(decodeTripleTerm(valueStore, firstQuad));
					long[] quad;
					while ((quad = heldTriples.next()) != null) {
						actualTripleTerms.add(decodeTripleTerm(valueStore, quad));
					}
					assertThat(actualTripleTerms)
							.as("the native reader must retain every committed RDF-star term ID across the resize; "
									+ "term values are decoded through fresh dictionary reads")
							.containsExactlyInAnyOrderElementsOf(expectedTripleTerms);
				}
			}

			assertThat(readRows(repository))
					.as("prepared checkpointing must preserve every statement and nested RDF-star value")
					.containsExactlyInAnyOrderElementsOf(expected);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void preparedBatchResizeRollbackCanRetryExactValues() throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), autoGrowConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();

		Model firstBatch = preparedRows(0, SEPARATE_BATCH_ROWS, 1);
		Model secondBatch = preparedQuotedRows(SEPARATE_BATCH_ROWS, SEPARATE_BATCH_ROWS);
		Model expected = new LinkedHashModel();
		expected.addAll(firstBatch);
		expected.addAll(secondBatch);
		try (ResizeLogCapture resizeLogs = ResizeLogCapture.open()) {
			SailSink failedSink = store.getBackingStore()
					.getExplicitSailSource()
					.sink(IsolationLevels.READ_COMMITTED);
			try {
				failedSink.approveAll(firstBatch);
				int resizesAfterFirstBatch = resizeLogs.valueResizeMessages().size();
				assertThat(resizesAfterFirstBatch)
						.as("the first prepared batch must reserve its own value footprint")
						.isGreaterThan(0);
				failedSink.approveAll(secondBatch);
				assertThat(resizeLogs.valueResizeMessages())
						.as("the retry must begin after a prepared-batch value checkpoint")
						.hasSizeGreaterThan(resizesAfterFirstBatch);
			} finally {
				failedSink.close();
			}

			assertThat(readRows(repository))
					.as("closing the failed sink must roll back its statements before retry")
					.isEmpty();
			Set<TripleTerm> secondBatchTerms = new HashSet<>();
			secondBatch.forEach(statement -> secondBatchTerms.add((TripleTerm) statement.getObject()));
			assertThat(readNativeTripleTerms((ValueStore) store.getBackingStore().getValueFactory()))
					.as("closing the failed sink must not publish second-batch RDF-star terms")
					.doesNotContainAnyElementsOf(secondBatchTerms);

			try (SailSink retrySink = store.getBackingStore()
					.getExplicitSailSource()
					.sink(IsolationLevels.READ_COMMITTED)) {
				retrySink.approveAll(expected);
				retrySink.flush();
			}

			assertThat(readRows(repository))
					.as("rollback after an intermediate value checkpoint must leave exact retryable RDF values")
					.containsExactlyInAnyOrderElementsOf(expected);
		} finally {
			repository.shutDown();
		}
	}

	private void exerciseSingleQuotedCommit(boolean holdReader) throws Exception {
		LmdbStore store = new LmdbStore(dataDir.toFile(), autoGrowConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			try (ResizeLogCapture resizeLogs = ResizeLogCapture.open()) {
				int initialRows = seedQuotedTripleTerms(repository, ROWS);
				List<String> beforeGrowth = resizeLogs.resizeMessages();
				resizeLogs.clear();
				if (holdReader) {
					try (SailDataset dataset = store.getBackingStore()
							.getExplicitSailSource()
							.dataset(IsolationLevels.READ_COMMITTED);
							CloseableIteration<? extends TripleTerm> triples = dataset.getTriples(null, PREDICATE,
									null);
							SailRepositoryConnection writer = repository.getConnection()) {
						assertThat(triples.hasNext()).as("preloaded quoted triples must be visible").isTrue();
						triples.next();
						commitSingleGrowth(writer, repository, initialRows, beforeGrowth, resizeLogs);
						int remaining = 0;
						while (triples.hasNext()) {
							triples.next();
							remaining++;
						}
						assertThat(remaining).as("the held read-committed cursor must retain the preloaded quoted rows")
								.isEqualTo(initialRows - 1);
					}
				} else {
					try (SailRepositoryConnection writer = repository.getConnection()) {
						commitSingleGrowth(writer, repository, initialRows, beforeGrowth, resizeLogs);
					}
				}

				assertThat(beforeGrowth)
						.as("preparing the quoted seed batch must grow the value map")
						.anyMatch(message -> message.contains("Resizing map from"));
				assertThat(countRows(repository)).as("a successful single commit must preserve every input row")
						.isEqualTo(initialRows + ROWS);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void commitSingleGrowth(SailRepositoryConnection writer, SailRepository repository, int initialRows,
			List<String> beforeGrowth, ResizeLogCapture resizeLogs) {
		writer.begin(IsolationLevels.READ_COMMITTED);
		try {
			addRows(writer, "quoted-growth-subject:", "quoted-growth-value:", 0, ROWS);
			writer.commit();
		} catch (RepositoryException failure) {
			failure.addSuppressed(new AssertionError(
					"single commit map diagnostics; before growth=" + beforeGrowth + "; after growth="
							+ resizeLogs.resizeMessages()));
			try {
				writer.rollback();
				int recoveredRows = countRows(repository);
				if (recoveredRows != initialRows) {
					failure.addSuppressed(new AssertionError(
							"failed single commit did not preserve the preloaded row count: " + recoveredRows));
				} else {
					failure.addSuppressed(new AssertionError("rollback recovery passed; rows=" + recoveredRows));
				}
			} catch (RepositoryException recoveryFailure) {
				failure.addSuppressed(recoveryFailure);
			}
			throw failure;
		}
	}

	private static int seedQuotedTripleTerms(SailRepository repository, int count) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.READ_COMMITTED);
			for (int i = 0; i < count; i++) {
				TripleTerm quoted = VF.createTripleTerm(
						VF.createIRI("urn:lmdb-autogrow:quoted-subject:" + i),
						PREDICATE,
						VF.createLiteral("quoted-object-" + i + "-" + "q".repeat(VALUE_LENGTH)));
				connection.add(VF.createIRI("urn:lmdb-autogrow:quoted-owner:" + i), PREDICATE, quoted);
			}
			connection.commit();
		}
		return count;
	}

	private static void addRows(SailRepositoryConnection connection, String subjectPrefix, String valuePrefix,
			int start, int count) {
		for (int i = start; i < start + count; i++) {
			connection.add(VF.createIRI("urn:lmdb-autogrow:" + subjectPrefix + i), PREDICATE,
					VF.createLiteral(valuePrefix + i + "-" + "x".repeat(VALUE_LENGTH)));
		}
	}

	private static Model preparedRows(int start, int count, int valueLength) {
		Model rows = new LinkedHashModel();
		for (int i = start; i < start + count; i++) {
			rows.add(VF.createBNode("b" + i), PREDICATE,
					VF.createLiteral("separate-batch-value-" + i + "-" + "p".repeat(valueLength)));
		}
		return rows;
	}

	private static Model preparedQuotedRows(int start, int count) {
		Model rows = new LinkedHashModel();
		for (int i = start; i < start + count; i++) {
			IRI quotedSubject = VF.createIRI("urn:lmdb-autogrow:prepared-quoted-subject:" + i);
			TripleTerm quoted = VF.createTripleTerm(quotedSubject, PREDICATE,
					VF.createLiteral("prepared-quoted-object-" + i + "-" + "q".repeat(VALUE_LENGTH)));
			rows.add(VF.createIRI("urn:lmdb-autogrow:prepared-owner:" + i), PREDICATE, quoted);
		}
		return rows;
	}

	private static TripleTerm decodeTripleTerm(ValueStore valueStore, long[] quad) throws Exception {
		return VF.createTripleTerm((Resource) valueStore.getValue(quad[0]),
				(IRI) valueStore.getValue(quad[1]), valueStore.getValue(quad[2]));
	}

	private static Set<TripleTerm> readNativeTripleTerms(ValueStore valueStore) throws Exception {
		long predicateId = valueStore.getId(PREDICATE);
		if (predicateId == LmdbValue.UNKNOWN_ID) {
			return Set.of();
		}
		Set<TripleTerm> terms = new HashSet<>();
		try (RecordIterator iterator = valueStore.getTripleTerms(-1, predicateId, -1)) {
			long[] quad;
			while ((quad = iterator.next()) != null) {
				terms.add(decodeTripleTerm(valueStore, quad));
			}
		}
		return terms;
	}

	private static Model readRows(SailRepository repository) {
		Model rows = new LinkedHashModel();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.READ_COMMITTED);
			try (RepositoryResult<Statement> result = connection.getStatements(null, PREDICATE, null, false)) {
				result.forEachRemaining(rows::add);
			}
			connection.commit();
		}
		return rows;
	}

	private static LmdbStoreConfig autoGrowConfig() {
		return new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(256L * 1024)
				.setValueDBSize(256L * 1024)
				.setAutoGrow(true)
				.setTripleTermIndexes("spoc");
	}

	private static int countRows(SailRepository repository) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.READ_COMMITTED);
			int count = 0;
			try (RepositoryResult<Statement> rows = connection.getStatements(null, PREDICATE, null, false)) {
				while (rows.hasNext()) {
					rows.next();
					count++;
				}
			}
			connection.commit();
			return count;
		}
	}

	private static final class ResizeLogCapture implements AutoCloseable {

		private final Logger tripleLogger = (Logger) LoggerFactory.getLogger(TripleStore.class);
		private final Logger valueLogger = (Logger) LoggerFactory.getLogger(ValueStore.class);
		private final Level previousTripleLevel = tripleLogger.getLevel();
		private final Level previousValueLevel = valueLogger.getLevel();
		private final boolean previousTripleAdditive = tripleLogger.isAdditive();
		private final boolean previousValueAdditive = valueLogger.isAdditive();
		private final ListAppender<ILoggingEvent> tripleAppender = new ListAppender<>();
		private final ListAppender<ILoggingEvent> valueAppender = new ListAppender<>();

		private ResizeLogCapture() {
			tripleLogger.setLevel(Level.DEBUG);
			tripleLogger.setAdditive(false);
			valueLogger.setLevel(Level.INFO);
			valueLogger.setAdditive(false);
			tripleAppender.start();
			valueAppender.start();
			tripleLogger.addAppender(tripleAppender);
			valueLogger.addAppender(valueAppender);
		}

		private static ResizeLogCapture open() {
			return new ResizeLogCapture();
		}

		private List<String> resizeMessages() {
			return List.of(tripleAppender, valueAppender)
					.stream()
					.flatMap(appender -> appender.list.stream())
					.map(ILoggingEvent::getFormattedMessage)
					.filter(message -> message.contains("resized map to") || message.contains("Resizing map from")
							|| message.contains("reserved triple map capacity"))
					.toList();
		}

		private List<String> valueResizeMessages() {
			return valueAppender.list.stream()
					.map(ILoggingEvent::getFormattedMessage)
					.filter(message -> message.contains("resized map to") || message.contains("Resizing map from"))
					.toList();
		}

		private void clear() {
			tripleAppender.list.clear();
			valueAppender.list.clear();
		}

		@Override
		public void close() {
			tripleLogger.detachAppender(tripleAppender);
			valueLogger.detachAppender(valueAppender);
			tripleAppender.stop();
			valueAppender.stop();
			tripleLogger.setLevel(previousTripleLevel);
			tripleLogger.setAdditive(previousTripleAdditive);
			valueLogger.setLevel(previousValueLevel);
			valueLogger.setAdditive(previousValueAdditive);
		}
	}
}
